from pathlib import Path
from html import escape as esc
import json,re
root=Path(__file__).resolve().parents[1]
books=json.loads((root/'content/books.json').read_text(encoding='utf-8'))['books']
css='''
.catalog-hero{padding:40px 0 28px;border-bottom:1px solid #d9e1e9;margin-bottom:24px;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:24px;align-items:center}.catalog-eyebrow{color:#446574;font-weight:700;letter-spacing:.12em;text-transform:uppercase;font-size:.76rem;margin:0 0 10px}.catalog-hero h1{font-size:clamp(2.2rem,5vw,3.5rem);line-height:1.08;margin:0 0 18px;color:#12354c}.catalog-hero p{max-width:660px}.catalog-switch{display:flex;gap:8px;flex-wrap:wrap;margin:22px 0 0}.catalog-switch a{padding:9px 16px;border:1px solid #abbcc9;border-radius:24px;font-weight:700;text-decoration:none}.catalog-switch a[aria-current]{background:#12354c;color:white;border-color:#12354c}.cover-stack{display:flex;gap:8px;padding:12px}.cover-stack img{width:92px;height:140px;object-fit:contain;filter:drop-shadow(3px 7px 6px #152a3c30);transform:rotate(-7deg)}.cover-stack img:nth-child(2){transform:translateY(-12px) rotate(5deg)}.catalog-tools{background:#f0f5f8;border:1px solid #dce5eb;padding:20px;border-radius:12px;margin:22px 0 32px}.catalog-tools label{display:block;font-weight:700;margin:0 0 7px}.catalog-tools input{width:100%;padding:12px 14px;border:1px solid #8da4b4;border-radius:6px;font:inherit;background:#fff;color:#172e40}.catalog-filters{display:flex;flex-wrap:wrap;gap:7px;margin-top:14px}.catalog-filters button{padding:8px 12px;background:white;border:1px solid #aabdc9;border-radius:20px;font:inherit;font-size:.9rem;cursor:pointer;color:#12354c}.catalog-filters button[aria-pressed=true]{background:#12354c;color:white}.catalog-status{margin:12px 0 0;font-size:.88rem;color:#496476}.catalog-group{margin:34px 0 50px;scroll-margin-top:20px}.catalog-group h2{font-size:1.65rem;margin:0 0 6px}.group-intro{margin:0 0 22px;color:#526572}.book-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:26px 20px}.book-card{min-width:0;background:#fff;border:1px solid #dde4e9;border-radius:10px;overflow:hidden;display:flex;flex-direction:column;transition:box-shadow .15s}.book-card:hover{box-shadow:0 6px 20px #17394b16}.book-cover{display:flex;justify-content:center;align-items:center;background:#f1f3f3;padding:19px 14px;height:245px}.book-cover img{max-width:100%;width:auto;height:207px;object-fit:contain;filter:drop-shadow(2px 5px 4px #172c3e25)}.book-info{padding:15px;display:flex;flex-direction:column;gap:10px;flex:1}.book-info h3{font-size:1.02rem;line-height:1.35;margin:0;color:#13374c}.book-info h3 a{color:inherit;text-decoration:none}.book-subtitle{font-size:.82rem;line-height:1.5;margin:0;color:#536675;overflow-wrap:anywhere}.book-series{font-size:.72rem;letter-spacing:.045em;text-transform:uppercase;color:#456f76;font-weight:700;margin:0}.book-action{margin-top:auto;padding-top:6px}.book-action>a{font-weight:700;font-size:.88rem}.book-formats{font-size:.76rem;color:#566977;margin:6px 0 0;display:flex;flex-wrap:wrap;gap:4px 10px}.catalog-end{padding:24px;border-radius:10px;background:#eef4f6;margin:30px 0}.catalog-end h2{margin-top:0}.catalog-end p{margin-bottom:0}.book-card[hidden],.catalog-group[hidden],[hidden]{display:none!important}input:focus-visible,button:focus-visible,a:focus-visible{outline:3px solid #b27017;outline-offset:3px}@media(max-width:1000px){.book-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.cover-stack img{width:72px;height:110px}}@media(max-width:700px){.catalog-hero{grid-template-columns:1fr;padding-top:24px}.cover-stack{display:none}.book-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:16px 12px}.book-cover{height:211px;padding:12px}.book-cover img{height:185px}.book-info{padding:12px}.catalog-tools{padding:14px}.book-info h3{font-size:.94rem}}@media(max-width:360px){.book-grid{grid-template-columns:1fr}}@media(prefers-reduced-motion:reduce){.book-card{transition:none}}
'''
labels={'kelly':('The Kelly Brothers Mysteries','The numbered mysteries, followed by more Kelly Brothers adventures.'),'skybridge':('The Skybridge Trilogy','The Waking, The Night Shift, and The Skybridge.'),'talefold':('TaleFold classics retold','Familiar classics, retold in today’s language.'),'fiction':('More fiction & imaginative adventures','Standalone stories, fantasy, and a zombie survival pocket guide.'),'homeschool':('Homeschool curriculum & workbooks','Browse full-year curricula and subject practice by title and grade.'),'explain':('Explain Like I’m 5','Big ideas made tiny: science, technology, and the world around us.'),'teaching':('Teaching & school resources','Classroom technology guides, substitute binders, and school office references.'),'practical':('Practical learning & reference','Explore preparedness, skills, cooking, and everyday reference guides.'),'journals':('Guided workbooks, planners & journals','Companion records and guided pages for learning, work, and daily life.'),'activities':('Coloring & activity books','Alphabet coloring and puzzle collections.')}
def short(b):
 t=re.sub(r' \(The Kelly Brothers Mysteries.*?\)$','',b['title'])
 t=re.sub(r' \(Explain Like I.m 5: Big Ideas Made Tiny\)$','',t)
 return t.split(': ',1) if ': ' in t else [t,'']
def card(b):
 title,sub=short(b);series=re.sub(r' of \d+(?=: The Kelly Brothers Mysteries)', '', b['series']);f=''.join('<a href="'+esc(x['url'],quote=True)+'" rel="noopener">'+esc(x['format'])+'</a>' for x in b['formats'])
 return '<article class="book-card" data-category="'+b['category']+'"><a class="book-cover" href="'+b['url']+'" aria-label="View '+esc(b['title'],quote=True)+' on Amazon"><img src="'+esc(b['image'],quote=True)+'" alt="Cover of '+esc(b['title'],quote=True)+'" width="210" height="315" loading="lazy" decoding="async"></a><div class="book-info">'+('<p class="book-series">'+esc(series)+'</p>' if series else '')+'<h3><a href="'+b['url']+'">'+esc(title)+'</a></h3>'+('<p class="book-subtitle">'+esc(sub)+'</p>' if sub else '')+'<div class="book-action"><a href="'+b['url']+'">View on Amazon <span aria-hidden="true">↗</span></a>'+('<p class="book-formats">'+f+'</p>' if f else '')+'</div></div></article>'
collections=[
 ('fiction','books','Fiction books','Find your next adventure.','Explore Jeremy Kelly’s fiction collection: the Kelly Brothers Mysteries, the Skybridge Trilogy, modern classic retellings, and standalone stories.'),
 ('education','textbooks','Textbooks & learning','A bookshelf for curious minds.','Browse Jeremy Kelly’s educational books, homeschool curricula, subject workbooks, science explainers, and teaching guides.'),
 ('activities','coloring-puzzles','Coloring & puzzles','A little color. A new challenge.','Explore Jeremy Kelly’s coloring books, alphabet activities, and puzzle collections.'),
 ('journals','journals','Journals & logbooks','Make room for your everyday.','Browse Jeremy Kelly’s journals, logbooks, planners, trackers, and guided personal workbooks. School planners and record books are collected here too.'),
 ('nonfiction','nonfiction','Nonfiction & practical guides','Learn something useful.','Explore Jeremy Kelly’s practical nonfiction: preparedness, hands-on skills, cooking, and everyday reference guides.')
]
for section,slug,label,heading,intro in collections:
 items=[b for b in books if b['section']==section];groups=[k for k in labels if any(b['category']==k for b in items)]
 stack=''.join('<img src="'+esc(b['image'],quote=True)+'" alt="" width="92" height="140">' for b in items[:3])
 tabs=''.join('<a href="/'+dest+'"'+(' aria-current="page"' if key==section else '')+'>'+esc(name)+'</a>' for key,dest,name,_,_ in collections)
 body='<section class="catalog-hero"><div><p class="catalog-eyebrow">The Jeremy Kelly collection</p><p class="intro">'+intro+'</p><div class="catalog-switch">'+tabs+'</div></div><div class="cover-stack" aria-hidden="true">'+stack+'</div></section>'
 body+='<div class="catalog-tools" hidden><label for="book-search">Search this collection</label><input id="book-search" type="search" placeholder="Search a title, series, subject…" autocomplete="off"><div class="catalog-filters" role="group" aria-label="Book categories"><button type="button" data-filter="all" aria-pressed="true">All books</button>'+''.join('<button type="button" data-filter="'+g+'" aria-pressed="false">'+esc(labels[g][0])+'</button>' for g in groups)+'</div><p id="book-count" class="catalog-status" role="status" aria-live="polite">'+str(len(items))+' books</p></div><p id="book-empty" hidden>No books match your search. Try another title or choose All books.</p>'
 for g in groups:
  chosen=[b for b in items if b['category']==g]
  if g=='kelly':chosen.sort(key=lambda b:int(re.search(r'Book (\d+)',b['series'])[1]) if re.search(r'Book (\d+)',b['series']) else 1000)
  if g=='skybridge':chosen.sort(key=lambda b:{'The Waking':0,'The Night Shift':1,'The Skybridge':2}[short(b)[0]])
  body+='<section class="catalog-group" data-group="'+g+'"><h2>'+esc(labels[g][0])+'</h2><p class="group-intro">'+esc(labels[g][1])+'</p><div class="book-grid">'+''.join(card(b) for b in chosen)+'</div></section>'
 body+='<aside class="catalog-end"><h2>Keep exploring</h2><p>'+ ' · '.join('<a href="/'+dest+'">'+esc(name)+'</a>' for key,dest,name,_,_ in collections if key!=section)+' · <a href="https://www.amazon.com/stores/Jeremy-Kelly/author/B0G31V7JQB/allbooks?ref=ap_rdr&amp;shoppingPortalEnabled=true">Visit Jeremy Kelly on Amazon</a></p><p class="catalog-status">Books by Jeremy Kelly. Covers and listings checked November 4, 2026. Amazon has current format, price, and availability details. Purchases support the author.</p></aside>'
 page={'slug':slug+'.html','title':label+' by Jeremy Kelly | Origami Penguin','description':intro,'heading':heading,'nav':'textbooks' if section=='education' else 'books','breadcrumbs':[{'name':'Home','url':'/'},{'name':label}],'body':body,'kind':'catalog','styles':css,'scripts':['js/book-catalog.js?v=2']}
 (root/'content/pages'/f'{slug}.json').write_text(json.dumps(page,ensure_ascii=False,indent=2),encoding='utf-8')
